/*
 * sylvac_ble.h - C API of the Sylvac BLE SDK (sylvac_ble.dll, libsylvac_ble.so).
 *
 * Connect Sylvac instruments through Sylvac dongles (BLED112, Bt5Smart): start a manager,
 * connect instruments by their Bluetooth address, take events with sylvac_ble_next_event or get
 * them in a callback. Every call returns at once; results come back as events.
 *
 * Memory: the library allocates events and lists; free them with the matching *_free call.
 * Strings are UTF-8 and NUL-terminated. Calling convention: cdecl (SYLVAC_BLE_CALL).
 */

