  /**
   * Firmware version, `"major.minor.patch"`.
   */
  const char *version;
  /**
   * The `bonded_mac_count` instruments bonded to this dongle, as read at its start, emptied by
   * `sylvac_ble_reset_connections`; NULL when there are none. Owned by the event or list, like
   * the strings.
   */
