  /**
   * Simultaneous connections the dongle supports.
   */
  uint32_t max_conn;
  uint32_t bonded_mac_count;
  uint32_t peripheral_count;
  /**
   * 1: `peripheral_count` reached `max_conn`; `sylvac_ble_start_connect_on` is then refused
   * with `SYLVAC_BLE_REJECT_CENTRAL_FULL`.
   */
